import pandas as pd

def clean(df):
    df = df.copy()

    if 'species' in df.columns:
        df['species'] = df['species'].astype('string').str.strip()

    if 'island' in df.columns:
        df['island'] = df['island'].astype('string').str.strip()
        island_map = {'biscoe': 'Biscoe', 'dream': 'Dream', 'torgersen': 'Torgersen'}
        df['island'] = df['island'].str.lower().map(island_map).fillna(df['island'])

    if 'body_mass_g' in df.columns:
        df['body_mass_g'] = pd.to_numeric(
            df['body_mass_g'].astype('string').str.replace(',', '', regex=False).str.strip(),
            errors='coerce'
        )

    for col in ['bill_length_mm', 'bill_depth_mm', 'flipper_length_mm', 'year']:
        if col in df.columns:
            df[col] = pd.to_numeric(df[col], errors='coerce')

    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['species', 'body_mass_g'])
    result = d.groupby('species', dropna=True)['body_mass_g'].mean()
    return {str(k): float(v) for k, v in result.items()}
